import{_ as e,o as t,c as r,ag as o}from"./chunks/framework.B3amng90.js";const s="/abu-aigc-guide/screenshots/create-image.webp",i="/abu-aigc-guide/screenshots/create-modes.webp",n="/abu-aigc-guide/screenshots/asset-history.webp",m=JSON.parse('{"title":"第一次创作","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md"}'),l={name:"getting-started.md"};function g(h,a,c,d,u,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="第一次创作" tabindex="-1">第一次创作 <a class="header-anchor" href="#第一次创作" aria-label="Permalink to &quot;第一次创作&quot;">​</a></h1><p>登录阿不创作后，可以从首页的一句话创作开始，也可以进入画布、短剧或爆款工作区。模型和可用额度由当前服务提供；如果列表里没有需要的能力，请联系服务支持。</p><h2 id="生成一张图片或一段视频" tabindex="-1">生成一张图片或一段视频 <a class="header-anchor" href="#生成一张图片或一段视频" aria-label="Permalink to &quot;生成一张图片或一段视频&quot;">​</a></h2><h3 id="写下你的想法" tabindex="-1">写下你的想法 <a class="header-anchor" href="#写下你的想法" aria-label="Permalink to &quot;写下你的想法&quot;">​</a></h3><p>打开 <strong>开拍 → 一句话</strong>，在输入框描述你想要的画面。需要参考图时，点击左侧的 <strong>＋</strong> 上传，或者点击 <strong>引用</strong> 从片库选择素材。也可以直接把图片拖进输入区。</p><p><a href="/abu-aigc-guide/screenshots/create-image.webp"><img src="'+s+'" alt="开拍页的一句话输入框，左侧可上传参考图，下方可选择模式和模型" loading="lazy"></a></p><p><em>开拍页的一句话创作区。点击截图可查看大图。</em></p><p>可以复制这段提示词试一试：</p><blockquote><p>一只橘猫趴在木窗台上，午后的阳光洒在它背上，窗外有虚化的银杏树，暖色调，写实摄影。</p></blockquote><h3 id="选择创作模式并提交" tabindex="-1">选择创作模式并提交 <a class="header-anchor" href="#选择创作模式并提交" aria-label="Permalink to &quot;选择创作模式并提交&quot;">​</a></h3><ol><li>点击输入框左下角的<strong>创作模式</strong>，选 <strong>图片生成</strong> 或 <strong>视频生成</strong>，再从旁边选择可用的模型。</li><li>检查当前模型提供的比例、时长或数量设置，以及页面的计价提示。</li><li>点击输入框右下角的 <strong>开始创作</strong>，在当前会话里查看进度和结果。</li></ol><p><a href="/abu-aigc-guide/screenshots/create-modes.webp"><img src="'+i+'" alt="创作模式菜单包括图片生成、视频生成、文本与分析和音频生成" loading="lazy"></a></p><p><em>左下角的创作模式菜单。</em></p><h3 id="找回生成结果" tabindex="-1">找回生成结果 <a class="header-anchor" href="#找回生成结果" aria-label="Permalink to &quot;找回生成结果&quot;">​</a></h3><p>在侧栏打开 <strong>片库 → 生成历史</strong>，切换 <strong>图片</strong>、<strong>视频</strong> 或 <strong>音频</strong>，也可以按来源和时间筛选。把想留用的素材加入 <strong>个人资产库</strong>，下次可在开拍页或画布中继续引用。</p><p><a href="/abu-aigc-guide/screenshots/asset-history.webp"><img src="'+n+'" alt="片库的生成历史标签和图片、视频、音频筛选入口" loading="lazy"></a></p><p><em>片库上方的类型和来源筛选。</em></p><h2 id="选一种适合的创作方式" tabindex="-1">选一种适合的创作方式 <a class="header-anchor" href="#选一种适合的创作方式" aria-label="Permalink to &quot;选一种适合的创作方式&quot;">​</a></h2><ul><li><strong>一句话</strong>：快速尝试一个想法，适合直接生成图片、视频或音频。</li><li><strong>画布</strong>：组合提示词和素材，逐步生成、连接和修改，适合多轮创作。</li><li><strong>短剧</strong>：从小说或剧本开始，整理故事、角色和分镜。</li><li><strong>爆款</strong>：围绕商品图片、卖点或参考链接编排营销短视频。</li></ul><h2 id="额度与任务" tabindex="-1">额度与任务 <a class="header-anchor" href="#额度与任务" aria-label="Permalink to &quot;额度与任务&quot;">​</a></h2><p>提交前留意页面展示的费用或平台额度提示。视频生成通常比图片等待更久；任务仍在处理中时，先查看任务状态，不要连续重复提交。模型不可用、额度不足或任务失败时，按<a href="/abu-aigc-guide/faq">常见问题</a>排查。</p><h2 id="素材与隐私" tabindex="-1">素材与隐私 <a class="header-anchor" href="#素材与隐私" aria-label="Permalink to &quot;素材与隐私&quot;">​</a></h2><p>上传前确认图片、视频、剧本及商品素材具有使用权限。不要上传账号凭证、API 密钥、客户隐私或不应发送给模型服务的机密资料。</p><h2 id="接下来" tabindex="-1">接下来 <a class="header-anchor" href="#接下来" aria-label="Permalink to &quot;接下来&quot;">​</a></h2><ul><li><a href="/abu-aigc-guide/workflows/canvas">用无限画布组合素材</a></li><li><a href="/abu-aigc-guide/workflows/drama">从剧本制作短剧</a></li><li><a href="/abu-aigc-guide/workflows/marketing">为商品制作营销视频</a></li></ul>',25)])])}const f=e(l,[["render",g]]);export{m as __pageData,f as default};
